export type AdType = "banner" | "interstitial" | "rewarded";
export type AdEventName = "initialized" | "ad_requested" | "ad_loaded" | "ad_shown" | "ad_clicked" | "ad_closed" | "reward_earned" | "ad_error";
export interface GameHubSDKOptions {
    /** Public game identifier created by your GameHub backend. */
    gameId: string;
    /** Optional developer identifier. */
    developerId?: string;
    /** Base URL of your GameHub API, e.g. https://api.example.com */
    apiBaseUrl?: string;
    /** Complete ad endpoint. If set, it overrides apiBaseUrl + /v1/sdk/ads/next. */
    adEndpoint?: string;
    /** Complete analytics endpoint. If set, analytics are POSTed here. */
    analyticsEndpoint?: string;
    /** Optional public SDK/API key sent as X-GameHub-Key. Never put a secret server key in browser code. */
    apiKey?: string;
    /** Allows the SDK to show built-in demo creatives when no ad server is configured. Default false. */
    testMode?: boolean;
    /** Interstitial frequency cap in milliseconds. Default 30000. */
    interstitialCooldownMs?: number;
    /** Optional request timeout. Default 8000ms. */
    requestTimeoutMs?: number;
    /** Additional metadata sent to your ad API. */
    metadata?: Record<string, unknown>;
}
export interface AdRequest {
    type: AdType;
    placementId?: string;
    width?: number;
    height?: number;
    metadata?: Record<string, unknown>;
}
export interface AdCreative {
    id: string;
    type: AdType;
    title?: string;
    body?: string;
    imageUrl?: string;
    html?: string;
    clickUrl?: string;
    impressionUrl?: string;
    clickTrackerUrl?: string;
    closeable?: boolean;
    reward?: {
        amount?: number;
        currency?: string;
        name?: string;
    };
    expiresAt?: string;
}
export interface AdResponse {
    ok?: boolean;
    ad?: AdCreative | null;
    error?: string;
}
export interface BannerOptions {
    containerId?: string;
    placementId?: string;
    width?: number;
    height?: number;
    autoCreate?: boolean;
}
export interface InterstitialOptions {
    placementId?: string;
}
export interface RewardedOptions {
    placementId?: string;
    onReward?: (reward?: AdCreative["reward"]) => void;
}
export interface SDKEvent {
    name: AdEventName;
    type?: AdType;
    creativeId?: string;
    message?: string;
    data?: Record<string, unknown>;
}
